tools.example:
model.component("comp1").geom("geom1").create("imp1", "Import");
model.component("comp1").geom("geom1").feature("imp1").set("filename", "C:/cad/housing.step");
model.component("comp1").geom("geom1").feature("imp1").set("knit", "solid");
model.component("comp1").geom("geom1").feature("imp1").set("healedges", "on");
model.component("comp1").geom("geom1").feature("imp1").importData();
model.component("comp1").geom("geom1").run();

model.component("comp1").geom("geom1").create("ch1", "Check");
model.component("comp1").geom("geom1").feature("ch1").selection("input").set("imp1");
model.component("comp1").geom("geom1").run("ch1");

model.component("comp1").geom("geom1").defeaturing("ShortEdges").selection("input").set("imp1");
model.component("comp1").geom("geom1").defeaturing("ShortEdges").set("entsize", "3e-3");
model.component("comp1").geom("geom1").defeaturing("ShortEdges").find();
model.component("comp1").geom("geom1").defeaturing("ShortEdges").deleteAll("dse1");

model.component("comp1").geom("geom1").defeaturing("SliverFaces").selection("input").set("imp1");
model.component("comp1").geom("geom1").defeaturing("SliverFaces").set("entsize", "2e-3");
model.component("comp1").geom("geom1").defeaturing("SliverFaces").find();
model.component("comp1").geom("geom1").defeaturing("SliverFaces").detail().setGroup(1);
model.component("comp1").geom("geom1").defeaturing("SliverFaces").delete("dsl1");

model.component("comp1").geom("geom1").defeaturing("SmallFaces").selection("input").set("imp1");
model.component("comp1").geom("geom1").defeaturing("SmallFaces").set("entsize", "1e-3");
model.component("comp1").geom("geom1").defeaturing("SmallFaces").find();
model.component("comp1").geom("geom1").defeaturing("SmallFaces").deleteAll("dsf1");

model.component("comp1").geom("geom1").defeaturing("DeleteSpikes").selection("input").set("imp1");
model.component("comp1").geom("geom1").defeaturing("DeleteSpikes").set("entsize", "1e-4");
model.component("comp1").geom("geom1").defeaturing("DeleteSpikes").find();
model.component("comp1").geom("geom1").defeaturing("DeleteSpikes").deleteAll("dsp1");

model.component("comp1").geom("geom1").create("det1", "DetachFaces");
model.component("comp1").geom("geom1").feature("det1").selection("input").set("imp1", 31, 32, 33);
model.component("comp1").geom("geom1").run();

model.component("comp1").geom("geom1").create("rfa1", "ReplaceFaces");
model.component("comp1").geom("geom1").feature("rfa1").selection("input").set("imp1", 55, 56, 57, 58);
model.component("comp1").geom("geom1").feature("rfa1").set("heal", "extend");
model.component("comp1").geom("geom1").run();

GeomSequence g = model.component("comp1").geom("geom1");
g.defeaturing("Fillets").selection("input").set("imp1");
g.defeaturing("Fillets").set("entsize", "2[mm]");
g.defeaturing("Fillets").find();
int n = g.defeaturing("Fillets").detail().size();
g.defeaturing("Fillets").detail().setGroup(1, 2);
g.defeaturing("Fillets").delete("dfi1");

model.component("comp1").geom("geom1").create("imp1", "Import");
model.component("comp1").geom("geom1").feature("imp1").set("filename", "planar_transformer_layout.xml");
model.component("comp1").geom("geom1").feature("imp1").set("grouping", "layer");
model.component("comp1").geom("geom1").feature("imp1").set("importtype", "shell");
model.component("comp1").geom("geom1").feature("imp1").importData();
// Application Library: ECAD_Import_Module/Tutorials/pcb_import_shell, pcb_import_nets, pcb_import_components

model.component("comp1").geom("geom1").feature("imp1").set("ignorecontvtx", "on");
model.component("comp1").geom("geom1").feature("imp1").set("elimshortedg", "on");
model.component("comp1").geom("geom1").feature("imp1").set("maxedglen", "5[um]");

model.component("comp1").geom("geom1").export().setType("oasis");
model.component("comp1").geom("geom1").export().setOasisApproxDetail("fine");
model.component("comp1").geom("geom1").exportFinal("C:/out/optimized_mask.oas");

model.param().set("L", "50[mm]");
model.component("comp1").geom("geom1").create("cad1", "LiveLinkSOLIDWORKS");
model.component("comp1").geom("geom1").feature("cad1").set("param", new String[]{"D1@Sketch1"});
model.component("comp1").geom("geom1").feature("cad1").set("paramexpr", new String[]{"L"});
model.component("comp1").geom("geom1").feature("cad1").importData();
// Application Library: LiveLink_for_SOLIDWORKS/bracket_optimization_llsw, busbar_llsw

model.param().loadFile("C:/data/params.xlsx", "Inputs", "A2");
model.func("int1").loadFile("C:/data/curve.xlsx", "Sheet1", "A1");
model.param().saveFile("C:/data/params_out.xlsx", "Out", "A1", true, true);

String[][] in = readExcelFile("user:///sections.xlsx", "Beams", "A2");
model.param().set("h", in[0][1]);
model.study("std1").run();
writeExcelFile("user:///results.xlsx", "Out", "A1", new String[][]{{"h", "stress"}, {in[0][1], toString(model.result().numerical("gev1").getReal()[0][0])}});
// Application Library: LiveLink_for_Excel/beam_section_calculator_llexcel

model.externalInterface().create("sim1", "SimulinkCosimulation");
model.externalInterface("sim1").set("filename", "thermal_actuator.fmu");
model.externalInterface("sim1").setIndex("inputname", "V_in", 0);
model.externalInterface("sim1").setIndex("inputvalue", "0", 0);
model.externalInterface("sim1").run();  // export
// Application Library: LiveLink_for_Simulink/thermal_actuator_llsimulink

